/// The sum `Output`.
public indirect enum Output: Hashable {
    case away(id: String, name: String)
    case device(id: String, moving: Bool)
    case nowhere

    public init(_ r: Reader) {
        switch r.variant() {
        case 0: self = .away(id: r.text(), name: r.text())
        case 1: self = .device(id: r.text(), moving: r.bool())
        case 2: self = .nowhere
        case let v: fatalError("Output: no variant \(v)")
        }
    }

    public init(json j: Any?) {
        let (t, o) = J.sum(j)
        switch t {
        case "Away": self = .away(id: J.text(o!["id"]), name: J.text(o!["name"]))
        case "Device": self = .device(id: J.text(o!["id"]), moving: J.bool(o!["moving"]))
        case "Nowhere": self = .nowhere
        default: fatalError("Output: no variant \(t)")
        }
    }

    public var json: String {
        switch self {
        case let .away(id, name): return "{\"Away\":" + J.obj(["\"id\":" + J.q(id), "\"name\":" + J.q(name)]) + "}"
        case let .device(id, moving): return "{\"Device\":" + J.obj(["\"id\":" + J.q(id), "\"moving\":" + String(moving)]) + "}"
        case .nowhere: return "\"Nowhere\""
        }
    }
}

